import React from "react";
import headerBg from "../img/projects/header-bg.png";

const Home = () => {
  return (
    <div style={{ textAlign: "center" }}>
      <h1>Hi, my name is John Doe</h1>
      <h2>a frontend developer</h2>
      <h3>with passion for learning and creating.</h3>

      <img
        src={headerBg}
        alt="Profile"
        style={{ width: "300px" }}
      />
    </div>
  );
};

export default Home;
